function log(action,detail='',meta={}){historyStore.add(action,detail,meta);renderHistory();if(ribbonContextKind==='history')showRibbonContext('history')}
function renderHistory(){const box=qs('#documentHistory');if(box)box.innerHTML=historyStore.list(250).map(x=>'<div class="historyItem"><b>'+escapeHtml(x.action)+'</b><span>'+escapeHtml(new Date(x.at).toLocaleString('fr-FR')+(x.detail?' · '+x.detail:''))+'</span></div>').join('')}
function renderSnapshotHistory(){const box=qs('#snapshotHistory');if(!box)return;const rows=snapshotHistory.list();box.innerHTML=rows.length?rows.map(x=>'<div class="historyItem snapshotRow'+(x.current?' current':'')+'"><b>'+escapeHtml(x.label)+'</b><span>'+escapeHtml(new Date(x.at).toLocaleTimeString('fr-FR'))+'</span>'+(x.canRestore?'<button type="button" data-restore-snapshot="'+x.index+'">Restaurer</button>':'<span class="devBadge">ÉTAT ACTUEL</span>')+'</div>').join(''):'<div class="hint">Aucun point de retour.</div>';qsa('[data-restore-snapshot]',box).forEach(b=>b.onclick=()=>run(async()=>{await snapshotHistory.restore(Number(b.dataset.restoreSnapshot));log('Restauration historique','Point '+b.dataset.restoreSnapshot);renderSnapshotHistory()}));const u=qs('#undoHistory'),r=qs('#redoHistory');if(u)u.disabled=!snapshotHistory.canUndo();if(r)r.disabled=!snapshotHistory.canRedo()}

function escapeHtml(s){return String(s??'').replace(/[&<>"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[m]))}
function renderSelectedFiles(){const state=renderSelectedFilesSummary(workspace,{countEl:'#selectedFilesCount',summaryEl:'#selectedFilesSummary',limit:12});vars.setRuntime({SELECTED_COUNT:state.selected});updateNamePreview();updateBatchStatus()}
function currentScope(){return qs('#pageScope').value}
function targetPages(){const p=engine.targetPages(currentScope());if(currentScope()==='selected'&&!p.length)toast('Cochez au moins une page');return p}
function markSection(id){openStudioSection(id)}
function extDot(name=''){const m=String(name).match(/(\.[^.]+)$/);return m?m[1]:''}
function currentStamp(){return stamps.find(s=>s.id===activeStamp)||stamps[0]}
function applyStampNaming(){const s=currentStamp();vars.setRuntime({STAMP_ID:s.id,STAMP_LABEL:s.label,STAMP_PREFIX:qs('#stampApplyNaming')?.checked?(qs('#stampNamePrefix')?.value||s.filenamePrefix||''):'',STAMP_SUFFIX:qs('#stampApplyNaming')?.checked?(qs('#stampNameSuffix')?.value||s.filenameSuffix||''):''});vars.setOperation({stamp:true,annot:true});updateNamePreview()}
function syncVariablesFromUi(){
 const map={INITIALS:'operatorInitials',CLIENT:'globalClient',PROJECT:'globalProject',REFERENCE:'globalReference',SITE:'globalSite',SERVICE:'globalService',CATEGORY:'globalCategory',TAG:'globalTag',TREATMENT:'globalTreatment'};
 for(const[k,id]of Object.entries(map)){const el=qs('#'+id);if(el)vars.set(k,el.value.trim())}
 for(const k of ['STAMP_DATE','DATE_A','DATE_B','DATE_C','DATE_D'])vars.set(k,qs('[data-date="'+k+'"]')?.value||today());
 vars.setRuntime({PAGE:engine.currentPage||'',PAGES:engine.pageCount||'',SELECTED_COUNT:workspace.selected().length,SOURCE:(qs('#sourceProvider')?.value||'local').toUpperCase(),OUTPUT:(qs('#outputProvider')?.value||'local').toUpperCase(),OCR_LANG:qs('#ocrLang')?.value||'',GRAY:qs('#optGray')?.value==='1'?'GRIS':'COULEUR',OUTPUT_FORMAT:(qs('#outputFormat')?.value||'pdf').toUpperCase()});
 if(qs('#operationFolder'))qs('#operationFolder').value=vars.values.TREATMENT||'TRAITEMENT';
 syncNameFlags()
}
function syncNameFlags(){vars.setOperation({ocr:qs('#suffixOcr')?.checked,dpi:qs('#suffixDpi')?.checked?Number(qs('#optDpi')?.value||150):null,jpeg:qs('#suffixJpeg')?.checked?Number(qs('#optJpeg')?.value||82):null,gray:qs('#suffixGray')?.checked,annot:qs('#suffixAnnot')?.checked||vars.operation.annot,fusion:qs('#suffixFusion')?.checked,stamp:vars.operation.stamp});updateNamePreview()}
function nameForFile(fileName,ext=extDot(fileName)||'.pdf'){
 const sp={prefix:vars.runtime.STAMP_PREFIX||'',suffix:vars.runtime.STAMP_SUFFIX||''},mode=qs('#namingMode')?.value||'classic';
 if(mode==='code')return vars.buildName(fileName,{prefix:sp.prefix,template:qs('#nameCodeTemplate')?.value||'{FILENAME}',suffix:sp.suffix,extension:ext,operationSuffix:true});
 return vars.buildName(fileName,{prefix:(qs('#namePrefix')?.value||'')+sp.prefix,template:qs('#nameTemplate')?.value||'{FILENAME}',suffix:(qs('#nameSuffix')?.value||'')+sp.suffix,extension:ext,operationSuffix:true})
}
function outputName(ext='.pdf'){syncVariablesFromUi();return nameForFile(engine.fileName,ext)}
function updateNamePreview(){const el=qs('#namePreview');if(el)el.textContent=nameForFile(engine.fileName,'.pdf')}
function renderVariables(){const keys=['FILENAME','FULLNAME','EXT','FOLDER','PATH','RELATIVE_PATH','DATE','TIME','DATETIME','YEAR','MONTH','MONTH_NUM','MONTH_NAME_FR','MONTH_NAME_EN','DAY','DAY_NUM','DAY_NAME_FR','DAY_NAME_EN','WEEK','PAGE','PAGES','INDEX','SELECTED_COUNT','FILESIZE','INITIALS','CLIENT','PROJECT','REFERENCE','SITE','SERVICE','CATEGORY','TAG','TREATMENT','STAMP_DATE','DATE_A','DATE_B','DATE_C','DATE_D','STAMP_ID','STAMP_LABEL','STAMP_PREFIX','STAMP_SUFFIX','SOURCE','OUTPUT','OUTPUT_FORMAT','OCR_LANG','GRAY','OP','DPI','JPEG'];const box=qs('#variableGrid');box.innerHTML='';for(const k of keys){const wrap=document.createElement('span');wrap.className='variableItem';const el=document.createElement('code');el.textContent='{'+k+'}';el.title='Copier '+el.textContent;el.onclick=async()=>{await navigator.clipboard?.writeText(el.textContent);toast(el.textContent+' copié')};const q=document.createElement('button');q.type='button';q.className='helpDot';q.textContent='?';q.dataset.helpKey='var-'+k;wrap.append(el,q);box.append(wrap)}const grid=qs('#dateGrid');grid.innerHTML='';for(const k of ['STAMP_DATE','DATE_A','DATE_B','DATE_C','DATE_D']){const l=document.createElement('label');l.className='dateRow';l.innerHTML='<span>'+({STAMP_DATE:'Date tampon',DATE_A:'Date A',DATE_B:'Date B',DATE_C:'Date C',DATE_D:'Date D'}[k])+' <button class="helpDot" type="button" data-help-key="var-'+k+'">?</button></span><input type="date" data-date="'+k+'" value="'+(vars.values[k]||today())+'">';grid.append(l)}qsa('[data-date]').forEach(x=>x.oninput=()=>syncVariablesFromUi());help.bind(box);help.bind(grid)}
function renderStampLibrary(){const box=qs('#stampLibrary');box.innerHTML='';for(const s of stamps){const row=document.createElement('div');row.className='stampPreset'+(s.id===activeStamp?' active':'');row.innerHTML='<button type="button">'+escapeHtml(s.label)+'</button><button type="button" title="Utiliser">✓</button>';row.querySelectorAll('button').forEach(b=>b.onclick=()=>{activeStamp=s.id;qs('#stampTemplate').value=s.template;qs('#stampNamePrefix').value=s.filenamePrefix||'';qs('#stampNameSuffix').value=s.filenameSuffix||'';renderStampLibrary();showRibbonContext('stamp')});box.append(row)}}
let renderGeneration=0,renderTimer=0;
function scheduleViewerRender(){clearTimeout(renderTimer);const gen=++renderGeneration;renderTimer=setTimeout(()=>renderViewer(gen),0)}
async function renderSelectableText(page,viewport,gen){
 const layer=qs('#textLayer');if(!layer||!engine.pdfjs||!viewport)return;
 layer.innerHTML='';layer.style.width=viewport.width+'px';layer.style.height=viewport.height+'px';layer.style.setProperty('--scale-factor',String(viewport.scale));
 if(typeof pdfjsLib.renderTextLayer!=='function')return;
 const p=await engine.pdfjs.getPage(page),tc=await p.getTextContent();if(gen!==renderGeneration)return;
 try{const task=pdfjsLib.renderTextLayer({textContentSource:tc,container:layer,viewport,textDivs:[]});await task?.promise}catch(e){console.debug('Text layer:',e?.message||e)}
}
async function renderViewer(gen=++renderGeneration){if(!engine.pdfjs){qs('#emptyViewer').hidden=false;return}qs('#emptyViewer').hidden=true;const canvas=qs('#pageCanvas'),zoom=Number(qs('#viewerZoom').value||1),vp=await engine.renderPage(canvas,engine.currentPage,zoom);if(gen!==renderGeneration)return;await renderSelectableText(engine.currentPage,vp,gen);if(gen!==renderGeneration)return;const wrap=qs('#pageCanvasWrap');wrap.style.width=canvas.width+'px';wrap.style.height=canvas.height+'px';wrap.style.minWidth='0';qs('#annotationLayer').style.width=canvas.width+'px';qs('#annotationLayer').style.height=canvas.height+'px';qs('#pageInfo').textContent=engine.currentPage+' / '+engine.pageCount;qs('#zoomInfo').textContent=Math.round(zoom*100)+' %';qs('#docStatus').textContent=engine.fileName+' · '+engine.pageCount+' page(s)';annotations.render();updateNamePreview();renderThumbs()}
function renderThumbs(){const strip=qs('#pageStrip'),oldTop=strip.scrollLeft;strip.innerHTML='';let draggedPage=null;for(let p=1;p<=engine.pageCount;p++){const t=document.createElement('div');t.className='pageThumb'+(p===engine.currentPage?' active':'')+(engine.selected.has(p)?' checked':'');t.dataset.page=p;t.draggable=true;const cb=document.createElement('input');cb.type='checkbox';cb.className='pageCheck';cb.checked=engine.selected.has(p);cb.setAttribute('aria-label','Sélectionner page '+p);cb.onclick=e=>e.stopPropagation();cb.onchange=e=>{engine.toggleSelected(p,e.target.checked);qs('#pageScope').value='selected'};const del=document.createElement('button');del.type='button';del.className='pageDeleteMini';del.title='Supprimer la page '+p;del.textContent='🗑';del.onclick=e=>{e.stopPropagation();run(async()=>{await engine.deletePages([p]);log('Suppression page','Page '+p);scheduleViewerRender()})};const c=document.createElement('canvas'),lab=document.createElement('div');lab.className='pageThumbLabel';lab.textContent='Page '+p;t.append(cb,del,c,lab);t.onclick=e=>{if(e.target===cb||e.target===del)return;engine.selectPage(p)};t.addEventListener('dragstart',()=>{draggedPage=p;t.classList.add('dragging')});t.addEventListener('dragend',()=>{draggedPage=null;t.classList.remove('dragging')});t.addEventListener('dragover',e=>{e.preventDefault();t.classList.add('dragOver')});t.addEventListener('dragleave',()=>t.classList.remove('dragOver'));t.addEventListener('drop',e=>{e.preventDefault();t.classList.remove('dragOver');if(!draggedPage||draggedPage===p)return;run(async()=>{await engine.movePage(draggedPage,p);log('Déplacement page','Page '+draggedPage+' → '+p);scheduleViewerRender()})});strip.append(t);engine.renderThumb(c,p,.16).catch(()=>{})}const add=document.createElement('button');add.type='button';add.className='pageThumb pageAddTile';add.innerHTML='<b>＋</b><span>Ajouter une page</span>';add.onclick=()=>run(async()=>{await engine.addBlank(engine.pageCount);log('Nouvelle page','Page '+engine.currentPage);scheduleViewerRender()});strip.append(add);strip.scrollLeft=oldTop;syncSelectionInfo()}
function syncSelectionInfo(){qs('#pageSelectionInfo').textContent=engine.selected.size+' / '+engine.pageCount+' page(s) cochée(s)';qsa('#pageStrip .pageThumb').forEach(t=>{const p=Number(t.dataset.page);t.classList.toggle('checked',engine.selected.has(p));const c=qs('.pageCheck',t);if(c)c.checked=engine.selected.has(p)})}
async function ensurePageCounts(){for(const item of workspace.items){if(item.meta?.pages!=null)continue;if(!/\.pdf$/i.test(item.name)){item.meta={...(item.meta||{}),pages:0};continue}try{const d=await PDFLib.PDFDocument.load(await item.file.arrayBuffer(),{ignoreEncryption:true});item.meta={...(item.meta||{}),pages:d.getPageCount()}}catch{item.meta={...(item.meta||{}),pages:0}}}workspace.render()}
async function loadItem(item){try{const rel=item.relativePath||item.name||'',parts=rel.split('/');vars.setRuntime({FOLDER:parts.length>1?parts.at(-2):'',PATH:rel,RELATIVE_PATH:rel,FILESIZE:item.file?.size||0});await engine.loadFile(item.file);vars.setRuntime({PAGE:engine.currentPage,PAGES:engine.pageCount});log('Ouverture',item.name);scheduleViewerRender()}catch(e){toast(e.message);setStatus('Erreur : '+e.message)}}
function renderFileHistory(){const box=qs('#fileHistory');if(box)box.innerHTML=workspace.history.slice(0,20).map(x=>'<div class="historyItem"><b>'+escapeHtml(x.name)+'</b><span>'+new Date(x.time).toLocaleString('fr-FR')+'</span></div>').join('')}
function structureTemplate(id=qs('#outputStructure')?.value||'root'){
 const t={root:'',treatment:'{TREATMENT}','year-month':'{YEAR}/{MONTH}','year-month-week':'{YEAR}/{MONTH}/S{WEEK}','treatment-date':'{TREATMENT}/{YEAR}/{MONTH}'};
 return id==='custom'?(qs('#outputPathTemplate')?.value||''):t[id]??''
}
function outputStateSummary(active=false){const fmt=qs('#outputFormat')?.value||'pdf',provider=qs('#outputProvider')?.value||'local',structure=qs('#outputStructure')?.value||'root',path=qs('#outputPathPreview')?.textContent||'',dest=qs('#destinationInfo')?.textContent||'';return (active?'✓ ACTIF · ':'')+'Format: '+({pdf:'PDF',same:'Format d’origine',zip:'ZIP'}[fmt]||fmt)+' · Destination: '+provider+(provider==='drive'?' [DÉVELOPPEMENT]':'')+' · Classement: '+structure+' · '+path+' · '+dest}
function refreshOutputState(active=outputActive){const el=qs('#outputStatePreview');if(el)el.textContent=outputStateSummary(active)}
function syncOutputUi(){
 const provider=qs('#outputProvider')?.value||'local',structure=qs('#outputStructure')?.value||'root',preset=structureTemplate(structure),path=qs('#outputPathTemplate');
 if(path&&structure!=='custom')path.value=preset;
 const resolvedPath=vars.resolve(structure==='custom'?(path?.value||''):preset,engine.fileName);
 const preview=qs('#outputPathPreview');if(preview)preview.textContent=resolvedPath||'Racine de destination';
 let mode='download';
 if(provider==='source')mode=structure==='root'?'same-source':'same-source-custom';
 else if(provider==='local')mode=structure==='root'?'manual-root':'custom-path';
 else if(provider==='download')mode='download';
 else if(provider==='drive')mode='drive';
 if(qs('#outputMode'))qs('#outputMode').value=['same-source','same-source-custom','custom-path','manual-root','download'].includes(mode)?mode:'download';
 vars.setRuntime({OUTPUT:provider.toUpperCase()});
 return{provider,structure,mode,pathTemplate:resolvedPath,operationFolder:vars.values.TREATMENT||'TRAITEMENT'}
 refreshOutputState();
}
function outputOptions(){syncVariablesFromUi();const o=syncOutputUi();return{mode:o.mode,pathTemplate:o.pathTemplate,operationFolder:o.operationFolder,granularity:qs('#archiveGranularity')?.value||'month'}}
async function saveBlobConfigured(blob,name,{forceDrive=false}={}){
 const out=syncOutputUi();
 if(forceDrive||out.provider==='drive'){if(!drive.connected)throw new Error('Connectez Google Drive');await drive.uploadPath(blob,name,out.pathTemplate||'','exports');log('Drive export',name,{provider:'drive',path:out.pathTemplate||''});return{kind:'drive',name}}
 const r=await workspace.writeBlob(blob,name,outputActive?outputOptions():{mode:'download'});log(r.kind==='download'?'Téléchargement':'Enregistrement',name,{provider:out.provider,path:out.pathTemplate});return r
}
function batchRenameRows(){syncVariablesFromUi();const current=workspace.current(),rows=workspace.selected().map((x,i)=>{const rel=x.relativePath||x.name,parts=rel.split('/');vars.setRuntime({INDEX:i+1,FOLDER:parts.length>1?parts.at(-2):'',PATH:rel,RELATIVE_PATH:rel,FILESIZE:x.file?.size||0});return{item:x,name:nameForFile(x.name,extDot(x.name))}});if(current){const rel=current.relativePath||current.name,parts=rel.split('/');vars.setRuntime({INDEX:'',FOLDER:parts.length>1?parts.at(-2):'',PATH:rel,RELATIVE_PATH:rel,FILESIZE:current.file?.size||0})}return rows}
function previewRenameSelection(){const rows=batchRenameRows(),box=qs('#renameBatchPreview');if(box)box.textContent=rows.length?rows.slice(0,20).map(x=>x.item.name+' → '+x.name).join('\n'):'Aucun fichier coché.';return rows}
async function exportRenamedZip(){const rows=batchRenameRows();if(!rows.length)throw new Error('Aucun fichier coché');const z=new JSZip();for(const r of rows)z.file(r.name,r.item.file);const blob=await z.generateAsync({type:'blob',compression:'DEFLATE',compressionOptions:{level:6}}),name=vars.resolve('{DATE:YYYY-MM-DD}_fichiers-renommes.zip',engine.fileName);await saveBlobConfigured(blob,name);log('Renommage en lot',rows.length+' fichier(s)');return{name,blob}}
